using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ─── 1. Strongly-typed metadata retrieval ───
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");

// Use it to serialize
string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized: {json}");

// ─── 2. Probe without throwing ───
// TryGetTypeInfo returns false (instead of throwing) when metadata isn't available.
// Use a resolver that only knows about int, so Person lookup fails.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new SpecificResolver<int>())
};

bool found = limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? probed);
Console.WriteLine();
Console.WriteLine($"TryGetTypeInfo(Person) on limited resolver → found={found}, info={probed?.Type.Name ?? "(null)"}");

found = limited.TryGetTypeInfo(typeof(int), out probed);
Console.WriteLine($"TryGetTypeInfo(int)    on limited resolver → found={found}, info={probed?.Type.Name ?? "(null)"}");

// ─── Helper types ───
record Person(string Name, int Age);

/// A minimal resolver that only resolves one specific type via the default mechanism.
sealed class SpecificResolver<TOnly> : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(TOnly) ? _inner.GetTypeInfo(type, options) : null;
}
